#!/usr/bin/env python3
"""Regenerate crates/meteorite-core/src/bundled.rs from assets/themes/*.

Run after adding, removing or renaming a bundled theme file:
    python3 scripts/gen-bundled.py
A unit test fails if the generated list and the directory disagree.
"""
import os

root = os.path.join(os.path.dirname(__file__), "..", "crates", "meteorite-core")
assets = os.path.join(root, "assets", "themes")
out = ['''//! Themes compiled into the binary, so `meteorite new site` and
//! `meteorite theme add <name>` work offline.
//!
//! GENERATED by scripts/gen-bundled.py; do not edit by hand.

use std::fs;
use std::path::Path;

use crate::error::{io_err, Result};

pub struct Bundled {
    pub name: &'static str,
    /// `(path relative to the theme dir, contents)`
    pub files: &'static [(&'static str, &'static str)],
}

impl Bundled {
    pub fn write_to(&self, dir: &Path) -> Result<()> {
        for (rel, body) in self.files {
            let path = dir.join(rel);
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).map_err(io_err(parent))?;
            }
            fs::write(&path, body).map_err(io_err(&path))?;
        }
        Ok(())
    }
}
''']
names = []
for theme in sorted(os.listdir(assets)):
    files = []
    for d, _, fs in os.walk(os.path.join(assets, theme)):
        for f in fs:
            files.append(os.path.relpath(os.path.join(d, f), os.path.join(assets, theme)).replace(os.sep, "/"))
    files.sort()
    const = theme.upper().replace("-", "_")
    out.append(f'static {const}: Bundled = Bundled {{\n    name: "{theme}",\n    files: &[')
    for f in files:
        out.append(f'        ("{f}", include_str!("../assets/themes/{theme}/{f}")),')
    out.append("    ],\n};\n")
    names.append(const)
out.append("static ALL: &[&Bundled] = &[" + ", ".join("&" + n for n in names) + "];\n")
out.append('''pub fn find(name: &str) -> Option<&'static Bundled> {
    ALL.iter().copied().find(|b| b.name == name)
}

pub fn names() -> Vec<&'static str> {
    ALL.iter().map(|b| b.name).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// Every file under assets/themes must be listed, and every listed file must exist.
    #[test]
    fn list_matches_assets_directory() {
        let base = Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/themes");
        for b in ALL {
            let mut on_disk = BTreeSet::new();
            let dir = base.join(b.name);
            let mut stack = vec![dir.clone()];
            while let Some(d) = stack.pop() {
                for e in fs::read_dir(&d).unwrap() {
                    let p = e.unwrap().path();
                    if p.is_dir() {
                        stack.push(p);
                    } else {
                        let rel = p.strip_prefix(&dir).unwrap();
                        on_disk.insert(rel.to_string_lossy().replace('\\\\', "/"));
                    }
                }
            }
            let listed: BTreeSet<String> = b.files.iter().map(|(p, _)| p.to_string()).collect();
            assert_eq!(
                listed, on_disk,
                "theme `{}`: run `python3 scripts/gen-bundled.py` and rebuild",
                b.name
            );
        }
        let dirs = fs::read_dir(&base).unwrap().count();
        assert_eq!(dirs, ALL.len(), "a theme directory is missing from bundled.rs");
    }
}
''')
open(os.path.join(root, "src", "bundled.rs"), "w").write("\n".join(out))
